// DEV-only browser preview bridge for the simplified shell. It serves the REAL Rust
// parser output for the bundled synthetic demo case (tests/fixtures, generated by
// `cargo test demo_write_preview_fixture -- --ignored`) and the real skill files.
// It never performs inference. main.js imports this only when import.meta.env.DEV.
import evidence from '../tests/fixtures/demo-evidence.json';
import findings from '../tests/fixtures/demo-findings.json';
import iocs from '../samples/demo/iocs.json';
import baseline from '../tests/fixtures/baseline-evidence.json';
import baselineFindings from '../tests/fixtures/baseline-findings.json';

const skillFiles = import.meta.glob('../src-tauri/skills/*.md', {query: '?raw', import: 'default', eager: true});

function parseSkill(text) {
  const [, front = '', body = ''] = text.replace(/\r\n/g, '\n').match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/) ?? [];
  const get = key => (front.match(new RegExp(`^${key}:\\s*(.*)$`, 'm'))?.[1] ?? '').trim();
  const preload = [...front.matchAll(/^\s+-\s+([a-z_]+)/gm)].map(m => ({tool: m[1], arguments: {}}));
  return {name: get('name'), description: get('description'), triggers: get('triggers').split(',').map(s => s.trim()).filter(Boolean), preload, always: false, body: body.trim(), builtin: true, overridden: false};
}

export function extendMock(base) {
  const skills = Object.values(skillFiles).map(parseSkill).sort((a, b) => a.name.localeCompare(b.name));
  let savedQueries = [];
  return async (name, args = {}) => {
    if (name === 'open_lookup') return `https://www.virustotal.com/gui/(preview)/${args.value}`;
    if (name === 'inv_list' || name === 'inv_running') return [];
    if (name.startsWith('inv_')) throw Error('Large investigations need the desktop backend (not available in the browser preview).');
    if (name === 'queries_list') return savedQueries;
    if (name === 'queries_save') {
      savedQueries = structuredClone(args.items);
      return null;
    }
    if (name === 'skill_save') return parseSkill(args.text);
    if (name === 'sample_materialize') {
      if (args.id === 'github-baseline') return {paths: baseline.map(e => `preview/${e.source}`), iocs: []};
      return {paths: evidence.map(e => `preview/${e.source}`), iocs};
    }
    if (name === 'import_file') {
      const file = [...evidence, ...baseline].find(e => args.path.endsWith(e.source));
      if (!file) throw Error('Browser preview can only import the bundled sample case.');
      return structuredClone(file);
    }
    if (name === 'preserve') return null;
    if (name === 'analyze') {
      const ids = new Set(args.events.map(e => e.id));
      return [...findings, ...baselineFindings].filter(f => f.evidence.every(id => ids.has(id)));
    }
    if (name === 'skill_list') return skills;
    if (name === 'skill_dir') return '(browser preview)';
    if (name === 'skill_source') return `---\nname: ${args.name}\n---\n${skills.find(s => s.name === args.name)?.body ?? ''}`;
    if (name === 'discover_local_ai') return {servers: [], files: [], scanned_folders: ['(browser preview)'], duration_ms: 0};
    if (name === 'embedded_connection') return null;
    if (name === 'ai_selftest') return {chat_ok: false, error: 'Browser preview makes no model requests.'};
    return base(name, args);
  };
}
